333	<script>
334	  const slides=[...document.querySelectorAll('.slide')];
335	  const counter=document.querySelector('.counter');
336	  let i=0;
337	  function show(n){
338	    i=Math.max(0,Math.min(slides.length-1,n));
339	    slides.forEach((s,k)=>s.classList.toggle('active',k===i));
340	    counter.textContent=(i+1)+' / '+slides.length;
341	  }
342	  // Gate QA : ?slide=N affiche la slide N seule, chrome masqué (capture PNG propre).
343	  const q=new URLSearchParams(location.search).get('slide');
344	  if(q!==null){ document.body.classList.add('capture'); show(parseInt(q,10)-1); }
345	  else { show(0); }
346	  // Mode pointeur (touche l) : le clic cesse de naviguer, le curseur devient un marqueur ambre,
347	  // et maintenir le bouton trace un trait qui s'efface en ~1,2 s. Sortie par l ou Échap.
348	  const dot=document.querySelector('.laser-dot');
349	  const ink=document.querySelector('.ink');
350	  const ctx=ink.getContext('2d');
351	  const hint=document.querySelector('.hint');
352	  const HINT_NAV='← → naviguer · f plein écran · l pointeur';
353	  const HINT_LASER='<b>pointeur</b> · clic pour souligner · l ou Échap pour sortir';
354	  let laser=false, drawing=false, prev=null;
355	  function sizeInk(){
356	    const r=window.devicePixelRatio||1;
357	    ink.width=innerWidth*r; ink.height=innerHeight*r;
358	    ctx.setTransform(r,0,0,r,0,0);
359	    ctx.lineCap='round'; ctx.lineJoin='round'; ctx.lineWidth=5;
360	    ctx.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--accent').trim();
361	  }
362	  function fade(){
363	    if(!laser) return;
364	    ctx.save();
365	    ctx.globalCompositeOperation='destination-out';
366	    // Sous destination-out le compositeur ne lit que l'alpha : le RGB est ignore, aucun pixel noir
367	    // n'est produit. C'est un effaceur a 6% par image, pas une couleur.
368	    ctx.fillStyle='rgba(0,0,0,0.06)'; // brand-exempt: alpha seul lu par destination-out, le RGB n'est jamais peint
369	    ctx.fillRect(0,0,innerWidth,innerHeight);
370	    ctx.restore();
371	    requestAnimationFrame(fade);
372	  }
373	  function setLaser(on){
374	    laser=on; drawing=false; prev=null;
375	    document.body.classList.toggle('laser',on);
376	    hint.innerHTML=on?HINT_LASER:HINT_NAV;
377	    if(on){ sizeInk(); requestAnimationFrame(fade); }
378	    else { ctx.clearRect(0,0,innerWidth,innerHeight); }
379	  }
380	  addEventListener('resize',()=>{ if(laser) sizeInk(); });
381	  document.addEventListener('mousemove',e=>{
382	    if(!laser) return;
383	    dot.style.left=e.clientX+'px'; dot.style.top=e.clientY+'px';
384	    if(drawing){
385	      if(prev){ ctx.beginPath(); ctx.moveTo(prev.x,prev.y); ctx.lineTo(e.clientX,e.clientY); ctx.stroke(); }
386	      prev={x:e.clientX,y:e.clientY};
387	    }
388	  });
389	  document.addEventListener('mousedown',e=>{ if(laser){ drawing=true; prev={x:e.clientX,y:e.clientY}; } });
390	  document.addEventListener('mouseup',()=>{ drawing=false; prev=null; });
391	  document.addEventListener('keydown',e=>{
392	    if(['ArrowRight',' ','PageDown'].includes(e.key)){e.preventDefault();show(i+1);}
393	    else if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(i-1);}
394	    else if(e.key==='f'){if(!document.fullscreenElement)document.documentElement.requestFullscreen?.();else document.exitFullscreen?.();}
395	    else if(e.key==='l'){setLaser(!laser);}
396	    else if(e.key==='Escape'&&laser){setLaser(false);}
397	  });
398	  document.addEventListener('click',e=>{ if(laser) return; show(i + (e.clientX < window.innerWidth*0.25 ? -1 : 1));});
399	</script>
